00111 bool Socket::Connect( const char* addr, uint16_t port )
00112 {
00113     assert( !IsValid() );
00114 
00115     if( m_ptr )
00116     {
00117         const auto c = connect( m_connSock, m_ptr->ai_addr, m_ptr->ai_addrlen );
00118         if( c == -1 )
00119         {
00120 #if defined _WIN32
00121             const auto err = WSAGetLastError();
00122             if( err == WSAEALREADY || err == WSAEINPROGRESS ) return false;
00123             if( err != WSAEISCONN )
00124             {
00125                 freeaddrinfo( m_res );
00126                 closesocket( m_connSock );
00127                 m_ptr = nullptr;
00128                 return false;
00129             }
00130 #else
00131             const auto err = errno;
00132             if( err == EALREADY || err == EINPROGRESS ) return false;
00133             if( err != EISCONN )
00134             {
00135                 freeaddrinfo( m_res );
00136                 close( m_connSock );
00137                 m_ptr = nullptr;
00138                 return false;
00139             }
00140 #endif
00141         }
00142 
