00148         fcntl( m_connSock, F_SETFL, flags & ~O_NONBLOCK );
00149 #endif
00150         m_sock.store( m_connSock, std::memory_order_relaxed );
00151         freeaddrinfo( m_res );
00152         m_ptr = nullptr;
00153         return true;
00154     }
