00178 #else
00179         int flags = fcntl( sock, F_GETFL, 0 );
00180         fcntl( sock, F_SETFL, flags | O_NONBLOCK );
00181 #endif
00182         if( connect( sock, ptr->ai_addr, ptr->ai_addrlen ) == 0 )
