00307 int Socket::RecvBuffered( void* buf, int len, int timeout )
00308 {
00309     if( len <= m_bufLeft )
00310     {
00311         memcpy( buf, m_bufPtr, len );
00312         m_bufPtr += len;
00313         m_bufLeft -= len;
00314         return len;
00315     }
00316 
00317     if( m_bufLeft > 0 )
00318     {
00319         memcpy( buf, m_bufPtr, m_bufLeft );
00320         const auto ret = m_bufLeft;
00321         m_bufLeft = 0;
00322         return ret;
00323     }
00324 
00325     if( len >= BufSize ) return Recv( buf, len, timeout );
00326 
00327     m_bufLeft = Recv( m_buf, BufSize, timeout );
00328     if( m_bufLeft <= 0 ) return m_bufLeft;
00329 
00330     const auto sz = len < m_bufLeft ? len : m_bufLeft;
00331     memcpy( buf, m_buf, sz );
00332     m_bufPtr = m_buf + sz;
00333     m_bufLeft -= sz;
00334     return sz;
00335 }
