00337 int Socket::Recv( void* _buf, int len, int timeout )
00338 {
00339     const auto sock = m_sock.load( std::memory_order_relaxed );
00340     auto buf = (char*)_buf;
00341 
00342     struct pollfd fd;
00343     fd.fd = (socket_t)sock;
00344     fd.events = POLLIN;
00345 
00346     if( poll( &fd, 1, timeout ) > 0 )
00347     {
00348         return recv( sock, buf, len, 0 );
00349     }
00350     else
00351     {
00352         return -1;
00353     }
00354 }
