00384 bool Socket::ReadImpl( char*& buf, int& len, int timeout )
00385 {
00386     const auto sz = RecvBuffered( buf, len, timeout );
00387     switch( sz )
00388     {
00389     case 0:
00390         return false;
00391     case -1:
00392 #ifdef _WIN32
00393     {
00394         auto err = WSAGetLastError();
00395         if( err == WSAECONNABORTED || err == WSAECONNRESET ) return false;
00396     }
00397 #endif
00398     break;
00399     default:
00400         len -= sz;
00401         buf += sz;
00402         break;
00403     }
00404     return true;
00405 }
