00451 static int addrinfo_and_socket_for_family( uint16_t port, int ai_family, struct addrinfo** res )
00452 {
00453     struct addrinfo hints;
00454     memset( &hints, 0, sizeof( hints ) );
00455     hints.ai_family = ai_family;
00456     hints.ai_socktype = SOCK_STREAM;
00457 #ifndef TRACY_ONLY_LOCALHOST
00458     const char* onlyLocalhost = GetEnvVar( "TRACY_ONLY_LOCALHOST" );
00459     if( !onlyLocalhost || onlyLocalhost[0] != '1' )
00460     {
00461         hints.ai_flags = AI_PASSIVE;
00462     }
00463 #endif
00464     char portbuf[32];
00465     sprintf( portbuf, "%" PRIu16, port );
00466     if( getaddrinfo( nullptr, portbuf, &hints, res ) != 0 ) return -1;
00467     int sock = socket( (*res)->ai_family, (*res)->ai_socktype, (*res)->ai_protocol );
00468     if (sock == -1) freeaddrinfo( *res );
00469     return sock;
00470 }
00471 
00472 bool ListenSocket::Listen( uint16_t port, int backlog )
00473 {
00474     assert( m_sock == -1 );
00475 
00476     struct addrinfo* res = nullptr;
00477 
00478 #if !defined TRACY_ONLY_IPV4 && !defined TRACY_ONLY_LOCALHOST
00479     const char* onlyIPv4 = GetEnvVar( "TRACY_ONLY_IPV4" );
00480     if( !onlyIPv4 || onlyIPv4[0] != '1' )
00481     {
00482         m_sock = addrinfo_and_socket_for_family( port, AF_INET6, &res );
00483     }
00484 #endif
00485     if (m_sock == -1)
00486     {
00487         // IPV6 protocol may not be available/is disabled. Try to create a socket
00488         // with the IPV4 protocol
00489         m_sock = addrinfo_and_socket_for_family( port, AF_INET, &res );
00490         if( m_sock == -1 ) return false;
00491     }
00492 #if defined _WIN32
00493     unsigned long val = 0;
00494     setsockopt( m_sock, IPPROTO_IPV6, IPV6_V6ONLY, (const char*)&val, sizeof( val ) );
00495 #elif defined BSD
00496     int val = 0;
00497     setsockopt( m_sock, IPPROTO_IPV6, IPV6_V6ONLY, (const char*)&val, sizeof( val ) );
00498     val = 1;
00499     setsockopt( m_sock, SOL_SOCKET, SO_REUSEADDR, &val, sizeof( val ) );
00500 #else
00501     int val = 1;
00502     setsockopt( m_sock, SOL_SOCKET, SO_REUSEADDR, &val, sizeof( val ) );
00503 #endif
00504     if( bind( m_sock, res->ai_addr, res->ai_addrlen ) == -1 ) { freeaddrinfo( res ); Close(); return false; }
00505     if( listen( m_sock, backlog ) == -1 ) { freeaddrinfo( res ); Close(); return false; }
00506     freeaddrinfo( res );
00507     return true;
00508 }
