00715     }
00716 
00717     m_sock = sock;
00718     return true;
00719 }
00720 
00721 void UdpListen::Close()
00722 {
00723     assert( m_sock != -1 );
00724 #ifdef _WIN32
00725     closesocket( m_sock );
00726 #else
00727     close( m_sock );
00728 #endif
00729     m_sock = -1;
00730 }
00731 
00732 const char* UdpListen::Read( size_t& len, IpAddress& addr, int timeout )
00733 {
00734     static char buf[2048];
00735 
00736     struct pollfd fd;
00737     fd.fd = (socket_t)m_sock;
00738     fd.events = POLLIN;
00739     if( poll( &fd, 1, timeout ) <= 0 ) return nullptr;
00740 
00741     sockaddr sa;
00742     socklen_t salen = sizeof( struct sockaddr );
00743     len = (size_t)recvfrom( m_sock, buf, 2048, 0, &sa, &salen );
00744     addr.Set( sa );
00745 
00746     return buf;
00747 }
00748 
00749 }
